operation EncodeAngle(q : Qubit, theta : Double) : Unit is Adj + Ctl {
    Ry(theta, q);
    S(q);
}

operation UseEncodeAngle(q : Qubit, ctrl : Qubit, theta : Double) : Unit {
    EncodeAngle(q, theta);                      // Ry(theta), then S
    Adjoint EncodeAngle(q, theta);               // compiler-generated inverse
    Controlled EncodeAngle([ctrl], (q, theta));  // apply the whole sequence only if ctrl is |1>
}

operation Teleport(msg : Qubit, here : Qubit, there : Qubit) : Unit {
    // here/there start as an entangled Bell pair: (|00> + |11>)/sqrt(2)
    H(here);
    CNOT(here, there);

    // Bell-basis change on the qubit to send (msg) and the sender's half of the pair (here)
    CNOT(msg, here);
    H(msg);

    // measure both of the sender's qubits -- these are the 2 classical bits
    let m1 = M(msg);
    let m2 = M(here);

    // classically-controlled correction on the receiver's qubit
    if m2 == One {
        X(there);
    }
    if m1 == One {
        Z(there);
    }
}

import math

def grover_optimal_iterations(N):
    return math.floor((math.pi / 4) * math.sqrt(N))

for N in [4, 16, 1_000_000]:
    print(N, grover_optimal_iterations(N))
