# Generalized amplitude amplification, one iteration
function oracle(state):
    for each basis_state in state:
        if is_marked(basis_state):
            flip_sign(basis_state)   # phase-flip marked items only, no probability change
    return state

function diffuser(state):
    reflect_about_mean(state)        # inversion about the average amplitude
    return state

function grover_iteration(state):
    state = oracle(state)
    state = diffuser(state)
    return state
